def amicable_numbers_sum(limit):
    def divisors_sum(n):
        """Helper function to calculate the sum of proper divisors of a number n."""
        div_sum = 1  # 1 is a proper divisor of any number greater than 1
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                div_sum += i
                if i != n // i:  # Add the paired divisor if it's not the square root
                    div_sum += n // i
        return div_sum

    amicable_sum = 0
    for a in range(2, limit + 1):
        b = divisors_sum(a)
        if b != a and b <= limit and divisors_sum(b) == a:
            amicable_sum += a

    return amicable_sum

# Example test
assert amicable_numbers_sum(999) == 504
