def count_Substrings(s):
    def digit_sum(substring):
        return sum(int(char) for char in substring)

    count = 0
    n = len(s)

    # Iterate over all possible starting and ending indices of substrings
    for i in range(n):
        for j in range(i + 1, n + 1):
            substring = s[i:j]
            # Check if the sum of digits equals the length of the substring
            if digit_sum(substring) == len(substring):
                count += 1

    return count

# Example usage and test
assert count_Substrings('112112') == 6
```

