def move_num(s):
    # Separate the numbers and letters
    letters = []
    numbers = []
    temp_num = ""

    for char in s:
        if char.isdigit():
            temp_num += char
        else:
            if temp_num:
                numbers.append(temp_num)
                temp_num = ""
            letters.append(char)

    # Append any remaining numbers
    if temp_num:
        numbers.append(temp_num)

    # Join letters and numbers back together
    return ''.join(letters) + ''.join(numbers)

# Example usage
assert move_num('I1love143you55three3000thousand') == 'Iloveyouthreethousand1143553000'
```

