def tuple_to_dict(input_tuple):
    """
    Converts a tuple into a dictionary where adjacent elements are used as key-value pairs.

    Args:
    input_tuple (tuple): A tuple of elements to convert.

    Returns:
    dict: A dictionary with key-value pairs created from adjacent elements of the tuple.
    """
    # Use dictionary comprehension to create key-value pairs from adjacent elements
    return {input_tuple[i]: input_tuple[i + 1] for i in range(0, len(input_tuple) - 1, 2)}

# Test cases
assert tuple_to_dict((1, 5, 7, 10, 13, 5)) == {1: 5, 7: 10, 13: 5}
assert tuple_to_dict((2, 4, 6, 8)) == {2: 4, 6: 8}
assert tuple_to_dict((1, 2)) == {1: 2}
assert tuple_to_dict(()) == {}
assert tuple_to_dict((9,)) == {}
